-- Tarea 2 Base de Datos - USM Postulaciones : PHP + SQL
-- ----------------------------------------------------------------------

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";


-- Creación de la base de datos y selección para su uso
-- --------------------------------------------------------
CREATE DATABASE IF NOT EXISTS `usm_postulaciones`;
USE `usm_postulaciones`;

SET FOREIGN_KEY_CHECKS = 0; -- Desactivamos temporalmente las comprobaciones de claves foráneas para evitar errores al insertar datos relacionados.


-- Creación de Catalogos y tablas principales
-- --------------------------------------------------------

-- Tabla: tamano_empresa
CREATE TABLE `tamano_empresa` (
  `id_tamano` int(11) NOT NULL,
  `des_empresa` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: empresa
CREATE TABLE `empresa` (
  `rut_empresa` varchar(15) NOT NULL,
  `nombre_empresa` varchar(100) NOT NULL,
  `id_tamano` int(11) NOT NULL,
  `nombre_representante` varchar(100) NOT NULL,
  `mail_representante` varchar(100) NOT NULL,
  `telefono_representante` varchar(20) NOT NULL,
  `convenio_marco` tinyint(1) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: estado_postulacion
CREATE TABLE `estado_postulacion` (
  `id_estado` int(11) NOT NULL,
  `descripcion` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: region
CREATE TABLE `region` (
  `id_region` int(11) NOT NULL,
  `nombre_region` varchar(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: sede
CREATE TABLE `sede` (
  `id_sede` int(11) NOT NULL,
  `nombre_sede` varchar(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: tipo_iniciativa
CREATE TABLE `tipo_iniciativa` (
  `id_tipo_iniciativa` int(11) NOT NULL,
  `des_iniciativa` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: tipo_integrante
CREATE TABLE `tipo_integrante` (
  `id_tipo_integrante` int(11) NOT NULL,
  `des_integrante` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: rol_usuario
CREATE TABLE `rol_usuario` (
  `id_rol` int(11) NOT NULL,
  `descripcion_rol` varchar(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: usuarios
CREATE TABLE `usuarios` (
  `id_usuario` int(11) NOT NULL,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `id_rol` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: postulacion
CREATE TABLE `postulacion` (
  `id_postulacion` int(11) NOT NULL,
  `fecha_postulacion` date NOT NULL,
  `id_sede` int(11) NOT NULL,
  `id_region_ejecucion` int(11) NOT NULL,
  `id_region_impacto` int(11) NOT NULL,
  `jefe_carrera` varchar(100) NOT NULL,
  `coordinador_proyectos` varchar(100) NOT NULL,
  `rut_empresa` varchar(15) NOT NULL,
  `id_tipo_iniciativa` int(11) NOT NULL,
  `nombre_iniciativa` varchar(150) NOT NULL,
  `objetivo` varchar(255) NOT NULL,
  `descripcion_solucion` varchar(255) NOT NULL,
  `resultados_esperados` varchar(255) NOT NULL,
  `id_estado` int(11) NOT NULL,
  `presupuesto_total` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: equipo_de_trabajo
CREATE TABLE `equipo_de_trabajo` (
  `id_equipo` int(11) NOT NULL,
  `id_postulacion` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: integrante
CREATE TABLE `integrante` (
  `id_integrante` int(11) NOT NULL,
  `id_equipo` int(11) NOT NULL,
  `rut_integrante` varchar(15) NOT NULL,
  `nombre` varchar(100) NOT NULL,
  `departamento_area` varchar(100) NOT NULL,
  `id_sede` int(11) NOT NULL,
  `email` varchar(100) NOT NULL,
  `telefono` varchar(20) DEFAULT NULL,
  `id_tipo_integrante` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Tabla: etapa
CREATE TABLE `etapa` (
  `id_etapa` int(11) NOT NULL,
  `id_postulacion` int(11) NOT NULL,
  `nombre_etapa` varchar(100) NOT NULL,
  `plazos_semanas` int(11) NOT NULL,
  `entregable` varchar(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;



