-- Indices y Llaves Primarias
-- Definimos las llaves primarias para cada tabla, así como los índices necesarios para optimizar las consultas y garantizar la integridad referencial.
-- --------------------------------------------------------

ALTER TABLE `empresa`
  ADD PRIMARY KEY (`rut_empresa`),
  ADD KEY `id_tamano` (`id_tamano`);

ALTER TABLE `equipo_de_trabajo`
  ADD PRIMARY KEY (`id_equipo`),
  ADD KEY `id_postulacion` (`id_postulacion`);

ALTER TABLE `estado_postulacion`
  ADD PRIMARY KEY (`id_estado`);

ALTER TABLE `etapa`
  ADD PRIMARY KEY (`id_etapa`),
  ADD KEY `id_postulacion` (`id_postulacion`);

ALTER TABLE `integrante`
  ADD PRIMARY KEY (`id_integrante`),
  ADD UNIQUE KEY `rut_integrante` (`rut_integrante`),
  ADD KEY `id_sede` (`id_sede`),
  ADD KEY `id_tipo_integrante` (`id_tipo_integrante`),
  ADD KEY `id_equipo` (`id_equipo`);

ALTER TABLE `postulacion`
  ADD PRIMARY KEY (`id_postulacion`),
  ADD KEY `id_sede` (`id_sede`),
  ADD KEY `id_region_ejecucion` (`id_region_ejecucion`),
  ADD KEY `id_region_impacto` (`id_region_impacto`),
  ADD KEY `rut_empresa` (`rut_empresa`),
  ADD KEY `id_tipo_iniciativa` (`id_tipo_iniciativa`),
  ADD KEY `id_estado` (`id_estado`);

ALTER TABLE `region`
  ADD PRIMARY KEY (`id_region`);

ALTER TABLE `sede`
  ADD PRIMARY KEY (`id_sede`);

ALTER TABLE `tamano_empresa`
  ADD PRIMARY KEY (`id_tamano`);

ALTER TABLE `tipo_iniciativa`
  ADD PRIMARY KEY (`id_tipo_iniciativa`);

ALTER TABLE `tipo_integrante`
  ADD PRIMARY KEY (`id_tipo_integrante`);

-- Restricciones de AUTO_INCREMENT
ALTER TABLE `equipo_de_trabajo` MODIFY `id_equipo` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=11;
ALTER TABLE `etapa` MODIFY `id_etapa` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=31;
ALTER TABLE `integrante` MODIFY `id_integrante` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=80;
ALTER TABLE `postulacion` MODIFY `id_postulacion` int(11) NOT NULL AUTO_INCREMENT, AUTO_INCREMENT=13;

-- Definición de Llaves Foráneas (Filtros relacionales)
ALTER TABLE `empresa` ADD CONSTRAINT `empresa_ibfk_1` FOREIGN KEY (`id_tamano`) REFERENCES `tamano_empresa` (`id_tamano`);
ALTER TABLE `equipo_de_trabajo` ADD CONSTRAINT `equipo_de_trabajo_ibfk_1` FOREIGN KEY (`id_postulacion`) REFERENCES `postulacion` (`id_postulacion`);
ALTER TABLE `etapa` ADD CONSTRAINT `etapa_ibfk_1` FOREIGN KEY (`id_postulacion`) REFERENCES `postulacion` (`id_postulacion`);
ALTER TABLE `integrante` ADD CONSTRAINT `integrante_ibfk_1` FOREIGN KEY (`id_sede`) REFERENCES `sede` (`id_sede`), ADD CONSTRAINT `integrante_ibfk_2` FOREIGN KEY (`id_tipo_integrante`) REFERENCES `tipo_integrante` (`id_tipo_integrante`), ADD CONSTRAINT `integrante_ibfk_3` FOREIGN KEY (`id_equipo`) REFERENCES `equipo_de_trabajo` (`id_equipo`);
ALTER TABLE `postulacion` ADD CONSTRAINT `postulacion_ibfk_1` FOREIGN KEY (`id_sede`) REFERENCES `sede` (`id_sede`), ADD CONSTRAINT `postulacion_ibfk_2` FOREIGN KEY (`id_region_ejecucion`) REFERENCES `region` (`id_region`), ADD CONSTRAINT `postulacion_ibfk_3` FOREIGN KEY (`id_region_impacto`) REFERENCES `region` (`id_region`), ADD CONSTRAINT `postulacion_ibfk_4` FOREIGN KEY (`rut_empresa`) REFERENCES `empresa` (`rut_empresa`), ADD CONSTRAINT `postulacion_ibfk_5` FOREIGN KEY (`id_tipo_iniciativa`) REFERENCES `tipo_iniciativa` (`id_tipo_iniciativa`), ADD CONSTRAINT `postulacion_ibfk_6` FOREIGN KEY (`id_estado`) REFERENCES `estado_postulacion` (`id_estado`);



-- Vistas del sistema // View
-- --------------------------------------------------------
DROP TABLE IF EXISTS `vista_postulaciones`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vista_postulaciones`  AS 
SELECT `p`.`id_postulacion` AS `id_postulacion`, `p`.`nombre_iniciativa` AS `nombre_iniciativa`, `e`.`nombre_empresa` AS `nombre_empresa`, `s`.`nombre_sede` AS `nombre_sede`, `r1`.`nombre_region` AS `region_ejecucion`, `r2`.`nombre_region` AS `region_impacto`, `p`.`presupuesto_total` AS `presupuesto_total`, `ep`.`descripcion` AS `estado` 
FROM (((((`postulacion` `p` join `empresa` `e` on(`p`.`rut_empresa` = `e`.`rut_empresa`)) join `sede` `s` on(`p`.`id_sede` = `s`.`id_sede`)) join `region` `r1` on(`p`.`id_region_ejecucion` = `r1`.`id_region`)) join `region` `r2` on(`p`.`id_region_impacto` = `r2`.`id_region`)) join `estado_postulacion` `ep` on(`p`.`id_estado` = `ep`.`id_estado`));



-- Procedimientos almacenados, funciones y disparadores // Stored Procedures, Functions and Triggers
-- --------------------------------------------------------
DELIMITER $$

-- Procedimiento: obtener_postulaciones
CREATE DEFINER=`root`@`localhost` PROCEDURE `obtener_postulaciones` ()   
BEGIN
    SELECT * FROM vista_postulaciones;
END$$

-- Función: calcular_iva
CREATE DEFINER=`root`@`localhost` FUNCTION `calcular_iva` (`presupuesto` DECIMAL(12,2)) RETURNS DECIMAL(12,2) DETERMINISTIC 
BEGIN
    RETURN presupuesto * 0.19;
END$$

-- Disparador: validar_presupuesto
CREATE TRIGGER `validar_presupuesto` BEFORE INSERT ON `postulacion` FOR EACH ROW 
BEGIN
    IF NEW.presupuesto_total < 0 THEN
        SET NEW.presupuesto_total = 0;
    END IF;
END$$

DELIMITER ;




