-- ── VISTAS PARA POWER BI ─────────────────────────────────────


DROP VIEW IF EXISTS `vista_postulaciones_gestion`;
CREATE VIEW `vista_postulaciones_gestion` AS
SELECT
    p.id_postulacion,
    p.fecha_postulacion,
    YEAR(p.fecha_postulacion)  AS anio,
    MONTH(p.fecha_postulacion) AS mes,
    p.nombre_iniciativa,
    p.jefe_carrera,
    p.coordinador_proyectos,
    p.presupuesto_total,
    e.rut_empresa,
    e.nombre_empresa,
    te.des_empresa          AS tamano_empresa,
    e.convenio_marco,
    s.nombre_sede           AS sede,
    re.nombre_region        AS region_ejecucion,
    ri.nombre_region        AS region_impacto,
    ti.des_iniciativa       AS tipo_iniciativa,
    ep.descripcion          AS estado
FROM postulacion p
LEFT JOIN empresa            e   ON p.rut_empresa          = e.rut_empresa
LEFT JOIN tamano_empresa     te  ON e.id_tamano             = te.id_tamano
LEFT JOIN sede               s   ON p.id_sede               = s.id_sede
LEFT JOIN region             re  ON p.id_region_ejecucion   = re.id_region
LEFT JOIN region             ri  ON p.id_region_impacto     = ri.id_region
LEFT JOIN tipo_iniciativa    ti  ON p.id_tipo_iniciativa    = ti.id_tipo_iniciativa
LEFT JOIN estado_postulacion ep  ON p.id_estado             = ep.id_estado;


SET FOREIGN_KEY_CHECKS = 1; -- Volvemos a activar las restricciones relacionales
COMMIT;
